import React, { useContext } from 'react';
import { Container } from 'react-bootstrap';
import Layout from '../common/Layout';
import { AuthContext } from '../../App';
import {
  FaUserGraduate,
  FaUserTie,
  FaUniversity,
  FaUserCheck,
  FaUserTimes,
  FaGraduationCap,
} from 'react-icons/fa';

function DashBoard() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const displayName =
    user.stdnm || user.stfnm || user.drvnm || user.emlid || 'User';

  const getGreeting = () => {
    const hr = new Date().getHours();
    if (hr < 12) return 'Good Morning';
    if (hr < 17) return 'Good Afternoon';
    return 'Good Evening';
  };

  const today = new Date();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });
  const dayDigit = today.toLocaleDateString('en-US', { day: '2-digit' });
  const monthYear = today.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });

  const stats = [
    {
      label: 'Total Students',
      value: '0',
      icon: <FaUserGraduate />,
      className: 'data-student',
    },
    {
      label: 'Total Staff',
      value: '0',
      icon: <FaUserTie />,
      className: 'data-staff',
    },
    {
      label: 'Total Classes',
      value: '0',
      icon: <FaUniversity />,
      className: 'data-class',
    },
    {
      label: 'Overall Attendance',
      value: '--',
      icon: <FaUserCheck />,
      className: 'data-attendance',
    },
  ];

  return (
    <Layout>
      <Container className="dashboard-screenshot-container">
        <section className="analytics-dashboard">
          <h2 className="dashboard-heading">
            {getGreeting()}, {String(displayName).toUpperCase()}! 👋
          </h2>
          <p className="dashboard-subheading">
            Here's what's happening in ABC Public School today.
          </p>

          <div className="dashboard-date-widget">
            <span className="day-label">{dayName}</span>
            <span className="day-number">{dayDigit}</span>
            <span className="month-label">{monthYear}</span>
          </div>

          <div className="dashboard-stat-list">
            {stats.map((item, i) => (
              <article className="dashboard-stat-row" key={item.label}>
                <span className="stat-icon-box">
                  {item.icon}
                </span>
                <div className="stat-text">
                  <div className="stat-label">{item.label}</div>
                  <div className="stat-value">{item.value}</div>
                  <div className="stat-caption">Current academic year</div>
                </div>
              </article>
            ))}
          </div>

          <div className="dashboard-absent-row">
            <span className="stat-icon-box">
              <FaUserTimes />
            </span>
            <div className="stat-text">
              <div className="stat-label">Students Absent</div>
              <div className="stat-value">0</div>
            </div>
          </div>

          <div className="dashboard-footer-line">
            <span className="footer-label">Current academic year</span>
          </div>
        </section>
      </Container>
    </Layout>
  );
}

export default DashBoard;
